const EUR = n => (Math.round(n*100)/100).toLocaleString('fr-FR',{minimumFractionDigits:2,maximumFractionDigits:2}) + ' €';

const STYLES = ['Blanc de blancs','Rosé','Extra-brut / nature','Millésimé','Grand Cru'];

const esc = value => String(value ?? '')
  .replaceAll('&','&amp;')
  .replaceAll('<','&lt;')
  .replaceAll('>','&gt;')
  .replaceAll('"','&quot;');

export function boutiqueSlug(p){
  return `${p.brand}-${p.name}`
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g,'-')
    .replace(/^-|-$/g,'');
}

export function boutiqueAnalysis(p){
  const text = `${p.name} ${p.tags.join(' ')}`.toLowerCase();
  const isRose = text.includes('rosé') || text.includes('rose');
  const isBdb = text.includes('blanc de blancs');
  const isBdn = text.includes('blanc de noirs');
  const isNature = text.includes('nature') || text.includes('extra-brut') || text.includes('extra brut') || text.includes('zero');
  const isDemi = text.includes('demi-sec') || text.includes('demi sec');
  const isVintage = p.tags.includes('Millésimé') || /\b(19|20)\d{2}\b/.test(p.name);
  const isGrandCru = text.includes('grand cru');
  const isPremierCru = text.includes('premier cru') || text.includes('1er cru');

  let style = 'Brut';
  let expected = 'équilibré, frais et polyvalent';
  let summary = 'Un brut polyvalent, particulièrement adapté à l’apéritif, aux célébrations et au début du repas.';
  let choose = 'vous cherchez une cuvée polyvalente, facile à placer à l’apéritif comme sur un début de repas.';
  let avoid = 'vous recherchez un style très tranché, très peu dosé ou au contraire franchement doux.';
  let pairings = ['Gougères et feuilletés', 'Poisson ou volaille légère', 'Apéritif'];
  let occasions = ['Apéritif', 'Célébration', 'Repas simple'];
  let gauges = {fraicheur:4, rondeur:3, puissance:3, accessibilite:5};

  if(isDemi){
    style='Demi-sec';
    expected='rond, fruité et plus doux';
    summary='Un champagne destiné aux palais qui apprécient davantage de douceur, plus cohérent avec le dessert qu’avec les produits iodés.';
    choose='vous aimez les champagnes ronds ou cherchez une bouteille pour un dessert peu sucré et fruité.';
    avoid='vous attendez une finale très sèche, minérale ou un champagne destiné aux huîtres.';
    pairings=['Tarte aux fruits', 'Fruits rouges', 'Dessert peu sucré'];
    occasions=['Dessert', 'Goûter festif', 'Célébration'];
    gauges={fraicheur:2,rondeur:5,puissance:3,accessibilite:4};
  } else if(isRose){
    style='Rosé';
    expected='fruité, expressif et gourmand';
    summary='Un rosé à privilégier pour son registre fruité et sa polyvalence, de l’apéritif à un plat délicat autour du saumon ou des fruits rouges.';
    choose='vous recherchez un champagne expressif, festif et facile à associer à une cuisine légèrement fruitée.';
    avoid='vous préférez un profil très minéral, austère ou exclusivement tourné vers les coquillages.';
    pairings=['Saumon ou thon', 'Volaille rosée', 'Fruits rouges'];
    occasions=['Apéritif', 'Cadeau', 'Dîner'];
    gauges={fraicheur:3,rondeur:4,puissance:3,accessibilite:4};
  } else if(isBdn){
    style='Blanc de noirs';
    expected='ample, vineux et structuré';
    summary='Un blanc de noirs ample et structuré, taillé pour la table et les plats qui demandent davantage de matière.';
    choose='vous cherchez de la présence, une texture plus ample et un champagne capable d’accompagner un plat.';
    avoid='vous souhaitez avant tout une expression très légère, citronnée et aérienne.';
    pairings=['Volaille rôtie', 'Champignons', 'Fromage affiné'];
    occasions=['Repas', 'Cadeau amateur', 'Dîner'];
    gauges={fraicheur:3,rondeur:4,puissance:5,accessibilite:3};
  } else if(isBdb){
    style='Blanc de blancs';
    expected='frais, précis et élancé';
    summary='Un blanc de blancs précis et élancé, particulièrement adapté à l’apéritif, aux coquillages et aux poissons fins.';
    choose='vous recherchez de la fraîcheur, de la précision et une bouteille adaptée aux produits de la mer.';
    avoid='vous préférez un champagne très vineux, ample ou dominé par une sensation de fruits rouges.';
    pairings=['Huîtres et coquillages', 'Crustacés', 'Poisson fin'];
    occasions=['Apéritif', 'Fruits de mer', 'Cadeau'];
    gauges={fraicheur:5,rondeur:2,puissance:2,accessibilite:4};
  } else if(isNature){
    style='Extra-brut / nature';
    expected='sec, direct et tendu';
    summary='Une cuvée peu dosée, destinée aux amateurs de champagnes secs et précis plutôt qu’à ceux qui recherchent d’abord la rondeur.';
    choose='vous appréciez les champagnes secs, droits et peu marqués par la liqueur de dosage.';
    avoid='vous recherchez une sensation ronde, douce ou très consensuelle.';
    pairings=['Coquillages', 'Sashimi', 'Fromage frais'];
    occasions=['Apéritif gastronomique', 'Repas marin', 'Découverte'];
    gauges={fraicheur:5,rondeur:1,puissance:3,accessibilite:2};
  }

  if(isVintage){
    summary += ' La mention millésimée invite à la considérer comme une cuvée plus singulière, à servir dans un verre assez large.';
    occasions = ['Cadeau', 'Repas', 'Moment marquant'];
    gauges.accessibilite=Math.max(2,gauges.accessibilite-1);
  }

  const classification = isGrandCru ? 'Grand Cru' : isPremierCru ? 'Premier Cru' : null;
  return {style,expected,summary,choose,avoid,pairings,occasions,gauges,classification,isVintage};
}

function card(p){
  const old = '';
  const tags = p.tags.map(t=>`<span class="bq-tag">${t}</span>`).join('');
  const key = p.tags.join('|').toLowerCase();
  const internalUrl = `/champagne/${p.id && !String(p.id).startsWith('shopify_') ? p.id : boutiqueSlug(p)}/`;
  return `<article class="bq-card" data-style="${key}" data-price="${p.price}">
      <a class="bq-media" href="${internalUrl}" aria-label="Voir l’analyse de ${esc(p.brand)} ${esc(p.name)}">
        <img loading="lazy" src="${esc(p.image)}" alt="${esc(p.brand)} ${esc(p.name)}">
      </a>
      <div class="bq-body">
        <div class="bq-brand">${esc(p.brand)}</div>
        <h3 class="bq-name"><a href="${internalUrl}">${esc(p.name)}</a></h3>
        <div class="bq-tags">${tags}</div>
        <div class="bq-foot">
          <div class="bq-price">${EUR(p.price)}${old}</div>
          <a class="bq-btn" href="${internalUrl}">Voir l’analyse</a>
        </div>
      </div>
    </article>`;
}

function gauge(label, value){
  return `<div class="bqp-gauge"><div><span>${label}</span><strong>${value}/5</strong></div><div class="bqp-track"><i style="width:${value*20}%"></i></div></div>`;
}

function editorialScene(p, analysis){
  const text=`${p.name} ${p.tags.join(' ')}`.toLowerCase();
  const accords=(p.details?.accords||[]).map(item=>item.token||'');
  const occasions=p.occ||[];
  if(text.includes('rosé') || text.includes('rose')){
    return {image:'https://images.unsplash.com/photo-1673872602569-c9a1c1bfe71f?q=80&w=1800&auto=format&fit=crop',label:'Moment conseillé',title:'À servir à l’apéritif ou avec une cuisine délicatement fruitée'};
  }
  if(accords.includes('accord_mer') || /blanc de blancs|extra-brut|nature/.test(text)){
    return {image:'https://images.unsplash.com/photo-1679694140422-aecfd3d5dd0b?q=80&w=1800&auto=format&fit=crop',label:'Accord privilégié',title:'Une cuvée pensée pour les produits de la mer'};
  }
  if(occasions.includes('occ_cadeau') || p.price>=70){
    return {image:'https://images.unsplash.com/photo-1606728000988-fbbec753b8ce?q=80&w=1800&auto=format&fit=crop',label:'Occasion',title:'Une bouteille à offrir ou à ouvrir pour un moment marquant'};
  }
  if(p.producerType==='vigneron'){
    return {image:'https://images.unsplash.com/photo-1635715070096-b4655b94edee?q=80&w=1800&auto=format&fit=crop',label:'Identité',title:'Le caractère d’un champagne de vigneron'};
  }
  return {image:'https://images.unsplash.com/photo-1498429152472-9a433d9ddf3b?q=80&w=1800&auto=format&fit=crop',label:'Service',title:`Un ${analysis.style.toLowerCase()} polyvalent pour l’apéritif et le début du repas`};
}

export function boutiqueProductMain(p, buildDate, catalogue=CHAMPAGNES){
  const generic=boutiqueAnalysis(p);
  const scores=p.details?.scores;
  const a=p.details ? {
    ...generic,
    summary:p.note,
    choose:p.details.advice,
    avoid:p.details.avoid,
    style:p.tags.join(' · '),
    expected:p.details.aromas.length ? p.details.aromas.join(', ') : generic.expected,
    pairings:p.details.accords.length ? p.details.accords.map(item=>item.d) : generic.pairings,
    occasions:p.occ.map(item=>({
      occ_apero:'Apéritif',occ_diner:'Repas',occ_cadeau:'Cadeau',
      occ_romantique:'Tête-à-tête',occ_fete:'Célébration'
    }[item]||item)),
    gauges:{
      fraicheur:scores.freshness,
      rondeur:scores.roundness,
      puissance:scores.power,
      accessibilite:Math.max(1,6-scores.complexity)
    },
    classification:p.tags.includes('Grand Cru')?'Grand Cru':p.tags.includes('Premier Cru')?'Premier Cru':null,
    isVintage:p.tags.includes('Millésimé')
  } : generic;
  const old = '';
  const scene=editorialScene(p,a);
  const tags = p.tags.map(t=>`<span class="bq-tag">${esc(t)}</span>`).join('');
  const technicalFacts=[
    `<span class="bqp-fact"><small>Style</small><strong>${esc(a.style)}</strong></span>`,
    a.classification ? `<span class="bqp-fact"><small>Classement</small><strong>${a.classification}</strong></span>` : '',
    a.isVintage ? `<span class="bqp-fact"><small>Élaboration</small><strong>Millésimé</strong></span>` : '',
    p.details?.dosage ? `<span class="bqp-fact"><small>Dosage</small><strong>${esc(p.details.dosage)}</strong></span>` : '',
    p.details?.grapes?.length ? `<span class="bqp-fact"><small>Cépages</small><strong>${esc(p.details.grapes.join(', '))}</strong></span>` : ''
  ].filter(Boolean).join('');
  const related = catalogue
    .filter(x=>x.id!==p.id && x.tags.some(t=>p.tags.includes(t)))
    .sort((x,y)=>Math.abs(x.price-p.price)-Math.abs(y.price-p.price))
    .slice(0,3).map(card).join('');
  const observedDate=(p.offerCheckedAt||`${buildDate}T12:00:00Z`).slice(0,10);
  const formattedDate = new Intl.DateTimeFormat('fr-FR',{day:'numeric',month:'long',year:'numeric'}).format(new Date(`${observedDate}T12:00:00Z`));
  const producerSource=p.officialSourceUrl
    ? `<a class="bqp-source" href="${esc(p.officialSourceUrl)}" target="_blank" rel="noopener">Voir la cuvée chez le producteur</a>`
    : '';
  const profileCopy=a.expected
    ? `Arômes dominants : ${esc(a.expected)}. ${a.gauges.rondeur>=4?'La rondeur donne de l’ampleur à l’ensemble.':a.gauges.puissance>=4?'La structure soutient une vraie présence à table.':a.gauges.fraicheur>=4?'La fraîcheur conduit l’ensemble.':'L’équilibre reste le trait dominant.'}`
    : a.summary;

  return `<section class="bqp"><div class="container">
    <a class="a-back" href="/champagnes/">‹ Retour à la sélection</a>
    <div class="bqp-hero">
      <div class="bqp-visual"><img src="${esc(p.image)}" alt="${esc(p.brand)} ${esc(p.name)}"></div>
      <div class="bqp-intro">
        <div class="bq-brand">${esc(p.brand)}</div>
        <h1>${esc(p.name)}</h1>
        <p class="bqp-lead">${a.summary}</p>
        <div class="bq-tags">${tags}</div>
        <div class="bqp-price"><strong>${EUR(p.price)}</strong>${old}</div>
        <a class="btn btn-primary btn-lg" data-product-id="${esc(p.id)}" data-direct-url="${esc(p.merchantSourceUrl||p.productUrl||'')}" href="${esc(p.aff||p.buyUrl||'')}" target="_blank" rel="sponsored nofollow noopener">Voir l’offre chez Bottle of Italy</a>
        <p class="bqp-partner">Lien affilié · Prix et disponibilité chez le partenaire, relevés le ${formattedDate}.</p>
      </div>
    </div>

    <article class="bqp-panel bqp-verdict"><div class="pblock-eyebrow">Notre analyse</div><h2>Pourquoi la choisir</h2>
      <div class="decision-grid"><div class="decision"><strong>Ce qui la distingue</strong><p>${a.choose}</p></div><div class="decision"><strong>Quand l’écarter</strong><p>${a.avoid}</p></div></div>
    </article>

    <div class="bqp-panel">
      <div class="pblock-eyebrow">Dans le verre</div><h2>Son profil</h2>
      <p class="bqp-copy">${profileCopy}</p>
      <div class="bqp-gauges">${gauge('Fraîcheur',a.gauges.fraicheur)}${gauge('Rondeur',a.gauges.rondeur)}${gauge('Puissance',a.gauges.puissance)}${gauge('Facilité d’accès',a.gauges.accessibilite)}</div>
    </div>

    <div class="bqp-scene" style="--scene:url('${scene.image}')">
      <div><div class="pblock-eyebrow">${scene.label}</div><h2>${scene.title}</h2></div>
    </div>

    <div class="bqp-grid">
      <article class="bqp-panel"><div class="pblock-eyebrow">À table</div><h2>Accords conseillés</h2><ul class="bqp-list">${a.pairings.map(x=>`<li>${x}</li>`).join('')}</ul></article>
      <article class="bqp-panel"><div class="pblock-eyebrow">Pour quel moment ?</div><h2>Occasions adaptées</h2><ul class="bqp-list">${a.occasions.map(x=>`<li>${x}</li>`).join('')}</ul></article>
    </div>

    <div class="bqp-panel bqp-technical">
      <div class="pblock-eyebrow">Fiche technique</div><h2>Les repères essentiels</h2>
      <div class="bqp-facts">${technicalFacts}</div>
      ${producerSource}
    </div>

    <div class="bqp-buy">
      <div><div class="pblock-eyebrow">Offre partenaire</div><h2>${esc(p.brand)} ${esc(p.name)}</h2><p>Vérifiez le prix final, le stock, le millésime et les frais de livraison avant de commander.</p></div>
      <a class="btn btn-primary btn-lg" data-product-id="${esc(p.id)}" data-direct-url="${esc(p.merchantSourceUrl||p.productUrl||'')}" href="${esc(p.aff||p.buyUrl||'')}" target="_blank" rel="sponsored nofollow noopener">Consulter l’offre partenaire</a>
    </div>

    ${related?`<div class="bqp-related"><div class="sec-head"><h2 class="h2">Dans un style proche</h2><p>Trois bouteilles proches par leur style et leur prix.</p></div><div class="bq-grid">${related}</div></div>`:''}
  </div></section>
  <style>
    .bq-name a{color:inherit;text-decoration:none}.bqp{padding:clamp(36px,6vw,84px) 0 90px;background:#F4F4F1;color:#14110c}
    .bqp-hero{display:grid;grid-template-columns:minmax(280px,.85fr) minmax(320px,1.15fr);gap:clamp(34px,7vw,92px);align-items:center;margin-top:28px}
    .bqp-visual{height:560px;border:1px solid #deded8;background:#fff;display:grid;place-items:center;padding:34px;overflow:visible;box-sizing:border-box}
    .bqp-visual img{display:block;width:auto!important;height:auto!important;max-width:100%;max-height:100%;object-fit:contain!important;object-position:center;mix-blend-mode:multiply;margin:auto}.bqp-intro h1{font-family:var(--display);font-size:clamp(40px,5.3vw,72px);font-weight:900;text-transform:uppercase;line-height:.95;letter-spacing:-.025em;margin:12px 0 22px}
    .bqp-lead{font-size:18px;line-height:1.75;color:#5f5a51;max-width:62ch}.bqp-price{display:flex;align-items:center;gap:12px;margin:28px 0 22px}.bqp-price>strong{font-size:30px}.bqp-partner,.bqp-muted{font-size:13px;line-height:1.65;color:#777067}.bqp-partner{margin-top:12px}
    .bqp-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:22px}.bqp-panel{background:transparent;border:0;border-top:1px solid #d7d2c8;padding:clamp(28px,4vw,44px) 0;margin-top:22px}.bqp-panel h2,.bqp-buy h2{font-family:var(--display);font-size:clamp(26px,3vw,38px);font-weight:800;line-height:1.04;margin:8px 0 18px}.bqp-panel p{line-height:1.7;color:#514c44}
    .bqp-copy{max-width:76ch}.bqp-gauges{display:grid;grid-template-columns:1fr 1fr;gap:22px 34px;margin-top:30px}.bqp-gauge>div:first-child{display:flex;justify-content:space-between;font-size:13px;margin-bottom:8px}.bqp-track{height:7px;background:#e5e5e0;overflow:hidden}.bqp-track i{display:block;height:100%;background:#806020}
    .bqp-scene{position:relative;isolation:isolate;min-height:390px;margin-top:22px;padding:clamp(30px,6vw,70px);display:flex;align-items:flex-end;overflow:hidden;background-image:linear-gradient(90deg,rgba(13,11,7,.83),rgba(13,11,7,.18)),var(--scene);background-size:cover;background-position:center;color:#fff}.bqp-scene:after{content:'';position:absolute;inset:0;z-index:-1;background:linear-gradient(180deg,transparent 45%,rgba(13,11,7,.38))}.bqp-scene>div{max-width:720px}.bqp-scene .pblock-eyebrow{color:#e6c777}.bqp-scene h2{font-family:var(--display);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1;text-transform:uppercase;margin:10px 0 0}
    .bqp-list{list-style:none;padding:0;margin:0;display:grid;gap:10px}.bqp-list li{padding:13px 16px;background:#F4F4F1}.bqp-list li:before{content:'✓';color:#806020;font-weight:700;margin-right:10px}
    .bqp-facts{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:0;margin:24px 0 0}.bqp-fact{display:flex;flex-direction:column;gap:5px;padding:18px 20px 18px 0;border-bottom:1px solid #d7d2c8}.bqp-fact small{color:#777067;text-transform:uppercase;letter-spacing:.08em;font-size:10px}.bqp-source{display:inline-flex;margin-top:22px;color:#6B4D18;font-weight:700;text-decoration:underline;text-underline-offset:3px}.bqp-buy{margin-top:22px;background:#17140f;color:#fff;border-radius:20px;padding:clamp(26px,4vw,44px);display:flex;justify-content:space-between;align-items:center;gap:28px}.bqp-buy p{color:#cbc5bb;margin:0}.bqp-related{margin-top:70px}
    .bqp-related .bq-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.bqp-related .bq-card{display:flex;flex-direction:column;background:#fff;border:1px solid #deded8;overflow:hidden;transition:transform .2s ease,box-shadow .2s ease}.bqp-related .bq-card:hover{transform:translateY(-4px);box-shadow:0 18px 40px -22px rgba(20,17,12,.28)}.bqp-related .bq-media{position:relative;display:flex;align-items:center;justify-content:center;height:280px;overflow:hidden;background:#fff;padding:22px;box-sizing:border-box}.bqp-related .bq-media img{display:block;width:auto!important;height:auto!important;max-width:100%;max-height:100%;object-fit:contain!important;object-position:center;mix-blend-mode:multiply;margin:auto}.bqp-related .bq-body{display:flex;flex-direction:column;gap:8px;padding:16px 16px 18px;flex:1}.bqp-related .bq-brand{font-size:11px;letter-spacing:.11em;text-transform:uppercase;color:#806020;font-weight:700}.bqp-related .bq-name{font-size:15px;line-height:1.32;font-weight:600;margin:0;min-height:2.4em}.bqp-related .bq-tags{display:flex;flex-wrap:wrap;gap:6px}.bqp-related .bq-tag{font-size:11px;color:#6f6a61;border:1px solid #deded8;padding:3px 9px}.bqp-related .bq-foot{margin-top:auto;display:flex;align-items:center;justify-content:space-between;gap:10px;padding-top:12px}.bqp-related .bq-price{display:flex;flex-direction:column;font-weight:700;font-size:16px}.bqp-related .bq-btn{background:#14110c;color:#fff;padding:9px 14px;font-size:12px;font-weight:600;text-decoration:none;white-space:nowrap}
    @media(max-width:760px){.bqp-hero,.bqp-grid{grid-template-columns:1fr}.bqp-visual{height:420px;padding:24px}.bqp-gauges{grid-template-columns:1fr}.bqp-buy{align-items:flex-start;flex-direction:column}.bqp-intro h1{font-size:42px}.bqp-related .bq-grid{grid-template-columns:1fr}.bqp-related .bq-media{height:300px}.bqp-scene{min-height:320px}}
  </style>`;
}

export function boutiqueMain(items=CHAMPAGNES){
  const cards = items.map(card).join('');
  const chips = ['Tous', ...STYLES].map((s,i)=>`<button class="bq-chip${i===0?' is-on':''}" data-f="${i===0?'':s.toLowerCase()}">${s}</button>`).join('');
  return `<section class="section"><div class="container">
    <div class="lead-head"><h1 class="h2">Sélection de champagnes</h1><p>${items.length} champagnes à découvrir et à commander, des grandes maisons aux vignerons indépendants : brut, rosé, blanc de blancs, extra-brut, pour chaque budget et chaque occasion.</p></div>

    <div class="boutique">
      <div class="bq-bar">
        <div class="bq-chips">${chips}</div>
        <div class="bq-sort">
          <label>Trier</label>
          <select id="bqSort">
            <option value="curated">Notre sélection</option>
            <option value="asc">Prix croissant</option>
            <option value="desc">Prix décroissant</option>
          </select>
        </div>
      </div>

      <div class="bq-grid" id="bqGrid">${cards}</div>

      <p class="bq-legal">Liens sponsorisés vers notre partenaire <strong>Bottle of Italy</strong>. Chaque prix correspond au dernier relevé de l’offre présentée ; le vendeur confirme le montant final et la disponibilité. L'abus d'alcool est dangereux pour la santé, à consommer avec modération. Vente réservée aux personnes majeures.</p>
    </div>
  </div></section>

  <style>
    .boutique{--bq-ink:#14110c;--bq-muted:#6f6a61;--bq-line:#e9e4da;--bq-gold:#806020;--bq-bg:#faf8f4;margin-top:26px}
    .bq-bar{display:flex;flex-wrap:wrap;gap:16px;align-items:center;justify-content:space-between;margin-bottom:26px}
    .bq-chips{display:flex;flex-wrap:wrap;gap:8px}
    .bq-chip{border:1px solid var(--bq-line);background:#fff;color:var(--bq-ink);border-radius:999px;padding:8px 15px;font-size:13px;font-weight:500;cursor:pointer;transition:.18s}
    .bq-chip:hover{border-color:var(--bq-gold);color:var(--bq-gold)}
    .bq-chip.is-on{background:var(--bq-ink);border-color:var(--bq-ink);color:#fff}
    .bq-sort{display:flex;align-items:center;gap:8px;color:var(--bq-muted);font-size:13px}
    .bq-sort select{border:1px solid var(--bq-line);border-radius:999px;padding:8px 12px;background:#fff;font:inherit;font-size:13px;color:var(--bq-ink);cursor:pointer}
    .bq-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(232px,1fr));gap:22px}
    .bq-card{display:flex;flex-direction:column;background:#fff;border:1px solid var(--bq-line);border-radius:16px;overflow:hidden;transition:transform .2s ease,box-shadow .2s ease}
    .bq-card:hover{transform:translateY(-4px);box-shadow:0 18px 40px -22px rgba(20,17,12,.28)}
    .bq-media{position:relative;display:flex;align-items:center;justify-content:center;height:340px;overflow:hidden;background:#fff;padding:24px;box-sizing:border-box}
    .bq-media img{display:block;width:auto!important;height:auto!important;max-width:100%;max-height:100%;object-fit:contain!important;object-position:center;mix-blend-mode:multiply;margin:auto}
    .bq-body{display:flex;flex-direction:column;gap:8px;padding:16px 16px 18px;flex:1}
    .bq-brand{font-size:11px;letter-spacing:.11em;text-transform:uppercase;color:var(--bq-gold);font-weight:700}
    .bq-name{font-size:15px;line-height:1.32;font-weight:600;color:var(--bq-ink);margin:0;min-height:2.4em}
    .bq-tags{display:flex;flex-wrap:wrap;gap:6px;margin-top:2px}
    .bq-tag{font-size:11px;color:var(--bq-muted);border:1px solid var(--bq-line);border-radius:999px;padding:3px 9px}
    .bq-foot{margin-top:auto;display:flex;align-items:center;justify-content:space-between;gap:10px;padding-top:12px}
    .bq-price{display:flex;flex-direction:column;line-height:1.15;font-weight:700;color:var(--bq-ink);font-size:16px}
    .bq-btn{background:var(--bq-ink);color:#fff;border-radius:999px;padding:9px 16px;font-size:13px;font-weight:600;text-decoration:none;white-space:nowrap;transition:.18s}
    .bq-btn:hover{background:var(--bq-gold)}
    .bq-legal{margin-top:30px;font-size:12px;line-height:1.6;color:var(--bq-muted);max-width:70ch}
    @media(max-width:560px){.bq-grid{grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:14px}.bq-media{height:250px;padding:16px}.bq-name{font-size:14px}}
  </style>

  <script>
  (function(){
    var grid=document.getElementById('bqGrid'); if(!grid) return;
    var cards=[].slice.call(grid.children);
    var chips=[].slice.call(document.querySelectorAll('.bq-chip'));
    chips.forEach(function(ch){ ch.addEventListener('click',function(){
      chips.forEach(function(c){c.classList.remove('is-on');}); ch.classList.add('is-on');
      var f=ch.getAttribute('data-f');
      cards.forEach(function(card){ card.style.display = (!f || card.getAttribute('data-style').indexOf(f)>-1) ? '' : 'none'; });
    });});
    var sort=document.getElementById('bqSort'); var original=cards.slice();
    sort && sort.addEventListener('change',function(){
      var v=sort.value, arr=original.slice();
      if(v==='asc') arr.sort(function(a,b){return a.dataset.price-b.dataset.price;});
      else if(v==='desc') arr.sort(function(a,b){return b.dataset.price-a.dataset.price;});
      arr.forEach(function(c){grid.appendChild(c);});
    });
  })();
  </script>`;
}
